       import 'dart:async';
       import 'package:flutter/material.dart';
       import 'package:flutter_riverpod/flutter_riverpod.dart';
       import '../../core/providers.dart';
       import '../../services/database/database.dart';
       import '../../services/mesh/device_discovery.dart';
       import 'device_detail_screen.dart';

       // FAB now: onPressed: () => showDialog<void>(context: context, builder: (_) => const _DeviceSearchDialog())

       class _DeviceSearchDialog extends ConsumerStatefulWidget {
         const _DeviceSearchDialog();
         @override
         ConsumerState<_DeviceSearchDialog> createState() => _DeviceSearchDialogState();
       }

       class _DeviceSearchDialogState extends ConsumerState<_DeviceSearchDialog> {
         final List<DiscoveredDevice> _found = [];
         StreamSubscription<DiscoveredDevice>? _subscription;
         String? _error;
         late final DeviceDiscoveryService _discovery;  // captured once, NOT re-read in dispose

         @override
         void initState() {
           super.initState();
           _discovery = ref.read(deviceDiscoveryProvider);
           _found.addAll(_discovery.currentDevices);
           _subscription = _discovery.discovered.listen(
             (device) {
               if (!mounted) return;
               setState(() => _found.add(device));
             },
             onError: (Object e) {
               if (!mounted) return;
               setState(() => _error = '$e');
             },
           );
           unawaited(_discovery.startScanning());
         }

         @override
         void dispose() {
           _subscription?.cancel();
           _discovery.stopScanning();  // uses stored field, not ref.read
           super.dispose();
         }

         @override
         Widget build(BuildContext context) {
           return AlertDialog(
             title: const Text('Gerät suchen'),
             content: SizedBox(
               width: double.maxFinite,
               child: Column(
                 mainAxisSize: MainAxisSize.min,
                 crossAxisAlignment: CrossAxisAlignment.start,
                 children: [
                   const Row(children: [
                     SizedBox(width: 16, height: 16, child: CircularProgressIndicator(strokeWidth: 2)),
                     SizedBox(width: 12),
                     Expanded(child: Text('Suche laeuft im WLAN (mDNS) ...', style: TextStyle(fontWeight: FontWeight.w500))),
                   ]),
                   const SizedBox(height: 12),
                   if (_error != null)
                     Text('Fehler: $_error', style: TextStyle(color: Theme.of(context).colorScheme.error))
                   else if (_found.isEmpty)
                     const Text('Noch kein Geraet gefunden.')
                   else
                     ConstrainedBox(
                       constraints: const BoxConstraints(maxHeight: 240),
                       child: ListView.builder(
                         shrinkWrap: true,
                         itemCount: _found.length,
                         itemBuilder: (context, index) {
                           final device = _found[index];
                           return ListTile(
                             dense: true,
                             leading: const Icon(Icons.wifi_tethering),
                             title: Text(device.name),
                             subtitle: Text('${device.ipAddress}:${device.port}'),
                           );
                         },
                       ),
                     ),
                   const SizedBox(height: 8),
                   Text(
                     'Gefundene Geraete melden sich automatisch in der Geraete-Liste '
                     'oben, sobald sie ihre Faehigkeiten gemeldet haben.',
                     style: Theme.of(context).textTheme.bodySmall,
                   ),
                 ],
               ),
             ),
             actions: [
               TextButton(onPressed: () => Navigator.of(context).pop(), child: const Text('Fertig')),
             ],
           );
         }
       }
       ```
