       class _SpyDeviceDiscoveryService extends DeviceDiscoveryService {
         _SpyDeviceDiscoveryService() : super(_NoopMqttService());
         int startCalls = 0;
         int stopCalls = 0;
         @override
         Future<void> startScanning({Duration interval = const Duration(seconds: 30)}) async {
           startCalls++;
         }
         @override
         void stopScanning() {
           stopCalls++;
         }
       }

       void main() {
