           await tester.pumpAndSettle();
           await tester.tap(find.text('Gerät suchen'));
           await tester.pump();
           expect(discovery.startCalls, 1);
           expect(discovery.stopCalls, 0);
           await tester.tap(find.text('Fertig'));
           await tester.pumpAndSettle();
