       class _DeviceSearchDialogState extends ConsumerState<_DeviceSearchDialog> {
         final List<DiscoveredDevice> _found = [];
         StreamSubscription<DiscoveredDevice>? _subscription;
         String? _error;
         late final DeviceDiscoveryService _discovery;  // captured once, NOT re-read in dispose

